#!/usr/bin/env bash
# Copyright (c) 2026, Harvey Mudd College
# SPDX-License-Identifier: Apache-2.0
# Build the VexRiscv Verilator testbench for CI.
# Usage: install-vexriscv.sh <install-dir>
# Cache key derives from sha256(this file); bump the pins below to invalidate. The testbench
# source checksum is pinned here too, so a changed testbench also changes the key.
#
# The core is LiteX's "imac" VexRiscv: the netlist VexRiscv_IMAC.v that
# litex-hub/pythondata-cpu-vexriscv ships, generated by its Makefile with
#   sbt compile "runMain vexriscv.GenCoreDefault --csrPluginConfig all --atomics true \
#     --compressedGen true --outputFile VexRiscv_IMAC"
# (SpinalHDL 1.9.4, see the netlist header). The netlist is used unchanged, so no JDK or sbt is
# needed. config/cores/vexriscv/README.md lists every generator option.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
INSTALL_DIR="${1:?Usage: install-vexriscv.sh <install-dir>}"
mkdir -p "$INSTALL_DIR/bin"
INSTALL_DIR="$(cd "$INSTALL_DIR" && pwd)"
JOBS="${JOBS:-$(nproc)}"

PYTHONDATA_COMMIT="642ecfed1c84460555d6d803d660cc60cfc1ecb6" # litex-hub/pythondata-cpu-vexriscv master, 2026-06-02
NETLIST_URL="https://raw.githubusercontent.com/litex-hub/pythondata-cpu-vexriscv/$PYTHONDATA_COMMIT/pythondata_cpu_vexriscv/verilog/VexRiscv_IMAC.v"
NETLIST_SHA256="25b6534fd2db84d7156859af7613311f5248f4d6269f2365e7afa90113ba9fdd"
TB_SHA256="639478c2a0506679d657da4420cddccf58906773d663daa5aa36a1b60fd4b101"
VERILATOR_VERSION="v5.036"

# 1. Verilator from source
if [ ! -x "$INSTALL_DIR/verilator/bin/verilator" ]; then
  git clone --depth 1 --branch "$VERILATOR_VERSION" https://github.com/verilator/verilator.git "$INSTALL_DIR/verilator-src"
  (
    cd "$INSTALL_DIR/verilator-src"
    autoconf
    ./configure --prefix="$INSTALL_DIR/verilator"
    make -j"$JOBS"
    make install
  )
  rm -rf "$INSTALL_DIR/verilator-src"
fi
export PATH="$INSTALL_DIR/verilator/bin:$PATH"

# 2. The netlist at the pinned commit, and the testbench from this repository
BUILD="$INSTALL_DIR/build"
rm -rf "$BUILD"
mkdir -p "$BUILD"
curl -fsSL "$NETLIST_URL" -o "$BUILD/VexRiscv_IMAC.v"
cp "$SCRIPT_DIR/vexriscv-tb.cpp" "$BUILD/"
(
  cd "$BUILD"
  printf '%s  %s\n' "$NETLIST_SHA256" VexRiscv_IMAC.v "$TB_SHA256" vexriscv-tb.cpp | sha256sum -c -
)

# 3. Verilate and build
(
  cd "$BUILD"
  verilator --cc --exe --build -j "$JOBS" -O3 --x-assign unique --x-initial unique \
    -Wno-fatal -Wno-WIDTH -Wno-UNOPTFLAT --top-module VexRiscv \
    VexRiscv_IMAC.v vexriscv-tb.cpp -o vexriscv-tb
)

install -m 0755 "$BUILD/obj_dir/vexriscv-tb" "$INSTALL_DIR/bin/vexriscv-tb"
install -m 0755 "$SCRIPT_DIR/run-vexriscv.sh" "$INSTALL_DIR/bin/run-vexriscv.sh"
rm -rf "$BUILD" "$INSTALL_DIR/verilator"
